<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request, query, session, can, type Page } from '../api'
import { money, orderKinds } from '../domain.js'
import StatusBadge from './StatusBadge.vue'
const emit=defineEmits<{navigate:[section:string]}>()
const metrics=ref<{label:string;value:number|null;section:string;symbol:string}[]>([{label:'全部订单',value:null,section:'orders',symbol:'▤'},{label:'待处理报价',value:null,section:'orders',symbol:'◷'},{label:'履约中',value:null,section:'orders',symbol:'↗'},{label:'已完成订单',value:null,section:'orders',symbol:'✓'}])
const summary=ref<Record<string,any>>({})
const recent=ref<any[]>([]),error=ref(''),loading=ref(true)
async function load(){loading.value=true;error.value='';try{const result=can('orders')?await Promise.all(['','awaiting_quote','fulfilling','completed'].map(status=>request<Page>('/orders'+query({page:1,page_size:5,status})))):[];result.forEach((page,index)=>metrics.value[index].value=page.total);recent.value=result[0]?.items||[];summary.value=can('reports')?await request('/reports/summary'):{}}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">业务概览</span><h1>你好，{{ session.user?.nickname||session.user?.name||session.user?.username||'管理员' }}</h1><p>{{ session.role==='platform'?'查看平台业务，处理待审事项与结算。':session.role==='merchant'?'管理自身船艇、服务与销售订单。':'管理本公司团队、客户与销售履约。' }}</p></div><button class="button" @click="load">刷新概览</button></div><p v-if="error" class="notice danger" role="alert">{{ error }}</p>
  <div v-if="can('orders')" class="metrics-grid"><button v-for="metric in metrics" :key="metric.label" class="metric-card" @click="emit('navigate',metric.section)"><div><span>{{ metric.label }}</span><strong>{{ metric.value===null?'—':metric.value }}</strong></div><span class="metric-symbol">{{ metric.symbol }}</span><small>查看订单 →</small></button></div>
  <div v-if="can('reports')" class="metrics-grid financial-metrics"><div v-for="metric in [{label:'累计实收',key:'paid_cents'},{label:'累计退款',key:'refund_cents'},{label:'已确认可分配利润',key:'profit_cents'},{label:'佣金账本净额',key:'commission_cents'}]" :key="metric.key" class="metric-card"><div><span>{{ metric.label }}</span><strong>{{ money(summary[metric.key]) }}</strong></div><small>服务端授权范围统计</small></div></div><div v-if="session.role!=='merchant'&&can('reports')" class="scope-banner"><span>客户数量 {{ summary.customer_count??'—' }} · 带看预约 {{ summary.appointment_count??'—' }}</span><span>包括待处理及历史记录</span></div><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><h2>最新订单</h2><button class="text-button" @click="emit('navigate','orders')">全部订单 →</button></div><div class="table-scroll"><table><thead><tr><th>订单编号</th><th>业务</th><th>金额</th><th>状态</th></tr></thead><tbody><tr v-if="loading"><td colspan="4" class="empty">正在加载…</td></tr><tr v-else-if="!recent.length"><td colspan="4" class="empty">暂无订单</td></tr><tr v-for="order in recent" v-else :key="order.id"><td class="cell-title">{{ order.order_no }}</td><td>{{ (orderKinds as Record<string,string>)[order.type]||order.type }}</td><td>{{ money(order.amount_cents) }}</td><td><StatusBadge :value="order.status" /></td></tr></tbody></table></div></section><section class="panel quick-panel"><div class="panel-heading"><h2>常用操作</h2></div><button v-if="can('orders')" class="quick-link" @click="emit('navigate','orders')"><span class="quick-icon">▤</span><div><strong>交易与合同</strong><small>订单、履约、合同版本</small></div><span>→</span></button><button v-if="session.role!=='merchant'&&can('users')" class="quick-link" @click="emit('navigate','users')"><span class="quick-icon">♙</span><div><strong>{{ session.role==='agency'?'公司团队':'组织与账号' }}</strong><small>角色归属及访问范围</small></div><span>→</span></button><button v-if="can('finance')" class="quick-link" @click="emit('navigate','ledger')"><span class="quick-icon">¥</span><div><strong>分红佣金账本</strong><small>利润确认与结算记录</small></div><span>→</span></button><div class="scope-note"><span>当前数据范围</span><strong>{{ session.role==='platform'?'全平台':`组织 #${session.user?.org_id||'—'}` }}</strong><p>访问权限以服务端身份和组织归属为准。</p></div></section></div>
</template>
